record.field:
import json
from datetime import timedelta
Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
today_str = fields.Date.today()
sensors = Sensor.search([
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id)
])
sensor_ids = [s.id for s in sensors]
last_readings_map = {}
if sensors:
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for sid, mtime in cr.fetchall():
        last_readings_map[sid] = mtime
plan = []
for sensor in sensors:
    device = sensor.device_id
    try:
        scfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except:
        scfg = {}
    try:
        dcfg = json.loads(device.remotecontrol_params or '{}') or {}
    except:
        dcfg = {}
    station_name = dcfg.get('device_id' or '')
    sensor_name = scfg.get('sensor_id' or '')
    start_cfg = scfg.get('start_date') or dcfg.get('start_date')
    last_m = last_readings_map.get(sensor.id)
    if last_m:
        try:
            initial_date = fields.Date.to_string(
                fields.Datetime.from_string(last_m) + timedelta(days=1)
            )
        except:
            initial_date = str(last_m)[:10]
    else:
        if start_cfg:
            initial_date = start_cfg[:10]
        else:
            year = today_str[:4]
            initial_date = '%s-01-01' % year
    stype = scfg.get('type', '').strip().lower()
    if stype not in ('pressure', 'flow', 'volume'):
        stype = 'unknown'
    plan.append({
        'sensor_id': sensor.id,
        'device_id': device.id,
        'station_name': station_name,
        'sensor_type': stype,
        'sensor_name': sensor_name,
        'initial_date': initial_date,
    })
bag['intages_plan'] = plan
bag['intages_plan_count'] = len(plan)

import json
import pytz
from datetime import datetime
Remote = self.remote_id
Device = env['mdm.measurement.device']
Sensor = env['mdm.measurement.device.sensor']
def parse_js_number(v):
    if v is None: return None
    if isinstance(v, dict):
        for k in ('$numberDecimal', '$numberLong', '$numberInt'):
            if k in v:
                v = v[k]; break
    if isinstance(v, str):
        v = v.strip().replace(",", ".")
        if v.lower() == "nan": return None
        try: return float(v)
        except: return None
    if isinstance(v, (int, float)): return float(v)
    return None
rows = bag.get("intages_rows") or []
total_processed = 0
total_upserts = 0
total_errors = 0
details = []
for r in rows:
    total_processed += 1
    device_id = r.get("device_id")
    ts        = r.get("timestamp")
    if not device_id or not ts:
        total_errors += 1
        if len(details) < 20:
            details.append({
                "device_id": device_id,
                "timestamp": ts,
                "status": "error",
                "error": "Missing fields"
            })
        continue

    pres_name = r.get("NombreSensorPresion")
    caud_name = r.get("NombreSensorCaudal")
    pres_val  = parse_js_number(r.get("ValorSensorPresion"))
    caud_val  = parse_js_number(r.get("ValorSensorCaudal"))
    vol_val   = parse_js_number(r.get("ValorVolumen"))
    sensor_candidates = []
    if pres_name and pres_val is not None:
        sensor_candidates.append({
            'name': pres_name,
            'value': pres_val,
            'expected_type': 'pressure'
        })
    if caud_name and vol_val is not None:
        sensor_candidates.append({
            'name': caud_name,
            'value': vol_val,
            'expected_type': 'volume'
        })
    if caud_name and caud_val is not None:
        sensor_candidates.append({
            'name': caud_name,
            'value': caud_val,
            'expected_type': 'flow'
        })
    if not sensor_candidates:
        continue
    sensor_found = None
    final_sensor_name = None
    final_value = None
    for candidate in sensor_candidates:
        potential_sensors = Sensor.search([
            ("device_id", "=", device_id)
        ])
        for ps in potential_sensors:
            try:
                scfg = json.loads(ps.remotecontrol_params or '{}') or {}
                stype = scfg.get('type', '').strip().lower()
                sensor_name_from_config = scfg.get('sensor_id' or '')
                if (stype == candidate['expected_type'] and
                    sensor_name_from_config == candidate['name']):
                    sensor_found = ps
                    final_sensor_name = candidate['name']
                    final_value = candidate['value']
                    break
            except:
                pass
        if sensor_found:
            break
    if not sensor_found:
        total_errors += 1
        if len(details) < 20:
            details.append({
                "device_id": device_id,
                "timestamp": ts,
                "sensor_name": final_sensor_name or "unknown",
                "status": "error",
                "error": "Sensor not found or type mismatch"
            })
        continue

    device = Device.browse(device_id)
    if not device.exists():
        total_errors += 1
        if len(details) < 20:
            details.append({
                "device_id": device_id,
                "timestamp": ts,
                "sensor_name": final_sensor_name,
                "status": "error",
                "error": "Device not found"
            })
        continue

    try:
        try:
            date_time_read = datetime.strptime(ts, "%Y-%m-%d %H:%M:%S")
            date_time_read = pytz.timezone('Europe/Madrid').localize(date_time_read)
            date_time_read = date_time_read.astimezone(pytz.timezone('UTC'))
            ts_utc = date_time_read.strftime("%Y-%m-%d %H:%M:%S")
        except:
            ts_utc = ts
        Remote.upsert(
            "mdm.measurement.device.sensor.reading",
            {
                "sensor_id": sensor_found.id,
                "measurement_time": ts_utc,
            },
            {
                "value": final_value,
                "device_id": device.id,
            }
        )
        total_upserts += 1

        if len(details) < 20:
            details.append({
                "device_id": device_id,
                "sensor_id": sensor_found.id,
                "sensor_name": sensor_found.name,
                "timestamp": ts,
                "value": final_value,
                "status": "success"
            })
    except Exception as e:
        total_errors += 1
        if len(details) < 20:
            details.append({
                "device_id": device_id,
                "sensor_id": sensor_found.id,
                "timestamp": ts,
                "value": final_value,
                "status": "error",
                "error": str(e)
            })
success_rate = "0.0%"
if total_processed:
    success_rate = "%.1f%%" % (float(total_upserts) / float(total_processed) * 100.0)
bag["intages_upsert_summary"] = {
    "executed_at": fields.Datetime.now(),
    "total_rows_processed": total_processed,
    "total_upserts": total_upserts,
    "total_errors": total_errors,
    "success_rate": success_rate,
}
bag["intages_upsert_details"] = details
Remote.message_post(
    body="[Intages] Upsert: %s processed, %s upserts, %s errors (success_rate=%s)" %
         (total_processed, total_upserts, total_errors, success_rate)
)
